def compute(vars):
    long_term_debt = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    percentage = (long_term_debt / total_contractual_obligations) * 100

    return {
        "value": percentage,
        "trace": {
            "long_term_debt": long_term_debt,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio": long_term_debt / total_contractual_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
